// Species pool for the visualization study (annual mean temperature, find the
// hottest/coldest dot). Generated offline from the occurrence data; prune
// freely (e.g. cultivated/introduced species). Selection criteria:
//   - plant species, 2,000-5,000 observations (not obscured, <= 500 m
//     coordinate uncertainty), with a temperature spread (min..max of the
//     displayed observations) of at least 30 F
//   - all but <= 1% of observations fit one 800x480 px map window at zoom 4;
//     `viewBox` is that window (lon/lat degrees), and only observations
//     inside it are displayed and counted (both the dots and the ground
//     truth) - the crop is purely geographic, never value-based
//   - `entropy`: normalized (0-1) Shannon entropy of where the displayed
//     observations fall across the window's 16x16 cells (low = clustered);
//     `q`: its quartile (1-4) across this pool
// Species whose window crosses the antimeridian are excluded.

export type StudyViewBox = {
  lonMin: number;
  lonMax: number;
  latMin: number;
  latMax: number;
};

export type PoolSpecies = {
  id: string;
  name: string;
  common: string;
  n: number;
  entropy: number;
  q: 1 | 2 | 3 | 4;
  spreadF: number;
  viewBox: StudyViewBox;
};

